// The build plans Ops hosts: one self-contained board page each, generated by
// plan-boards/build.py into public/<key>/, each with its own shared store.
//
// Every board works the same way — a planning row has a typed status until it
// is started in Ops, and from then on its column is derived from GitHub (see
// app/lib/plan-store.ts). What differs is its name, and the words its columns
// use, because each plan was written with its own.

import { STAGE } from "@/app/lib/progress";

export type Closed = null | "completed" | "not_planned";

export type PlanBoard = {
  key: string;
  /** How people refer to it: "MITRA", "SENTINEL", "SpatialCast Pro". */
  name: string;
  /** The heading of its card on the Ops board. */
  title: string;
  /**
   * The ladder in this board's words. One place per board, so the bands cannot
   * drift. Null when the board has no column that says it — the row keeps the
   * status it had, and its drawer shows the stage.
   */
  columnFor: (progress: number, closed: Closed) => string | null;
  /**
   * The repository the plan is built in (owner/name). Starting a task offers it
   * first; another repository can still be picked for work that belongs there.
   */
  repo?: string;
};

const ladder = (review: string, notPlanned: string | null) => (progress: number, closed: Closed) => {
  if (closed === "not_planned") return notPlanned;
  if (closed || progress >= STAGE.merged) return "Done";
  if (progress >= STAGE.pr_open) return review;
  if (progress >= STAGE.branched) return "In progress";
  return "To do";
};

export const PLAN_BOARDS: Record<string, PlanBoard> = {
  mitra: {
    key: "mitra", name: "MITRA", title: "MITRA app build", columnFor: ladder("In review", "Deferred (v1.1)"),
    repo: "ihelprobotics/mitra-healthtech_app",
  },
  // SENTINEL's plan has no deferred column, and "Needs verification" is its
  // word for a change waiting on review.
  sentinel: { key: "sentinel", name: "SENTINEL", title: "SENTINEL elderly-care build", columnFor: ladder("Needs verification", null) },
  // Written on SENTINEL's template, so it has SENTINEL's columns.
  spatialcast: {
    key: "spatialcast", name: "SpatialCast Pro", title: "SpatialCast Pro build", columnFor: ladder("Needs verification", null),
    repo: "ihelprobotics/spatial-immersion",
  },
};

/** The board for a route's `[board]` segment, or null for one that does not exist. */
export function planBoard(key: string): PlanBoard | null {
  return Object.hasOwn(PLAN_BOARDS, key) ? PLAN_BOARDS[key] : null;
}

export const unknownBoard = (key: string) =>
  `There is no "${key}" build board. The boards are: ${Object.keys(PLAN_BOARDS).join(", ")}.`;
